import {DatabaseSync} from 'node:sqlite';

// One short-lived connection per operation; SQLite bounds lock waits to 250ms.
function withDb<T>(path:string, operation:(d:DatabaseSync)=>T):T {
  const d=new DatabaseSync(path);
  try { d.exec('PRAGMA busy_timeout=250'); return operation(d); }
  finally { d.close(); }
}
export function init(path:string) {
  return withDb(path,d=>d.exec('CREATE TABLE jobs(id TEXT PRIMARY KEY,payload TEXT,dueAt INTEGER,status TEXT,worker TEXT,token INTEGER,leaseUntil INTEGER,result TEXT)'));
}
export function enqueue(path:string,j:{id:string;payload:string;dueAt:number}) {
  withDb(path,d=>d.prepare("INSERT INTO jobs VALUES(?,?,?,'pending',NULL,0,NULL,NULL)").run(j.id,j.payload,j.dueAt));
}
export async function claim(path:string,o:{now:number;worker:string;leaseMs:number}) {
  if(!Number.isSafeInteger(o.leaseMs)||o.leaseMs<=0) throw new RangeError('leaseMs must be a positive safe integer');
  const leaseUntil=o.now+o.leaseMs;
  if(!Number.isFinite(o.now)||!Number.isFinite(leaseUntil)||leaseUntil<=o.now) throw new RangeError('lease time must be finite and advance now');
  return withDb(path,d=>{
    // A single write statement owns candidate selection and mutation. No unlocked read.
    // Tokens remain exactly representable as JS numbers; exhausted jobs fail closed.
    const row=d.prepare(`UPDATE jobs SET status='processing',worker=?,token=token+1,leaseUntil=?
      WHERE id=(SELECT id FROM jobs
        WHERE (status='pending' AND dueAt<=?) OR (status='processing' AND leaseUntil<=?)
        ORDER BY dueAt,id LIMIT 1)
      AND token<9007199254740991
      RETURNING id,worker,token,leaseUntil,payload`).get(o.worker,leaseUntil,o.now,o.now);
    return row ? {id:row.id,worker:row.worker,token:row.token,leaseUntil:row.leaseUntil,payload:row.payload} : null;
  });
}
export function complete(path:string,c:{id:string;worker:string;token:number},result:string,o:{now:number}) {
  if(!Number.isFinite(o.now)) throw new RangeError('now must be finite');
  return withDb(path,d=>Number(d.prepare(`UPDATE jobs SET status='done',result=?
    WHERE id=? AND status='processing' AND worker=? AND token=? AND leaseUntil>?`)
    .run(result,c.id,c.worker,c.token,o.now).changes)>0);
}
export function readJobs(path:string) {
  return withDb(path,d=>d.prepare('SELECT * FROM jobs ORDER BY id').all());
}

import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {Worker} from 'node:worker_threads';
import {spawnSync} from 'node:child_process';
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {performance} from 'node:perf_hooks';
import {init,enqueue,claim,complete,readJobs} from './service.ts';
const directory=mkdtempSync(join(tmpdir(),'lease-fixed-')); let sequence=0;
const fixture=()=>{const path=join(directory,`${sequence++}.db`);init(path);return path;};
const add=(path,id,dueAt=0)=>enqueue(path,{id,payload:`payload:${id}`,dueAt});
const options=(now=0,worker='a',leaseMs=10)=>({now,worker,leaseMs});
const child=(action,path,data={})=>{const result=spawnSync(process.execPath,[fileURLToPath(new URL('./worker.mjs',import.meta.url)),action,path,JSON.stringify(data)],{encoding:'utf8',timeout:5000});assert.equal(result.status,0,result.stderr);return JSON.parse(result.stdout);};
const tests=[]; async function test(name,fn){await fn();tests.push(name);console.log(`PASS ${name}`);}
try{
  const v=new DatabaseSync(':memory:');console.log(JSON.stringify({node:process.version,sqlite:v.prepare('SELECT sqlite_version() AS version').get().version}));v.close();
  await test('B2-R1: Promise callers and eligibility/order/future starvation',async()=>{
    const p=fixture();add(p,'future',100);add(p,'b',0);add(p,'a',0);
    const [a,b]=await Promise.all([claim(p,options()),claim(p,options(0,'b'))]);
    assert.equal(a.id,'a');assert.equal(b.id,'b');assert.equal(a.payload,'payload:a');assert.deepEqual(Object.keys(a),['id','worker','token','leaseUntil','payload']);
    assert.equal(await claim(p,options()),null);assert.equal((await claim(p,options(100))).id,'a');
    const q=fixture();add(q,'one');const pair=await Promise.all([claim(q,options()),claim(q,options(0,'b'))]);assert.equal(pair.filter(Boolean).length,1);
  });
  await test('B2-R1: three real 8-connection synchronized races',async()=>{
    for(let run=0;run<3;run++){
      const p=fixture();add(p,'one');let release;const gate=new Promise(r=>release=r);let ready=0;
      const outcomes=await Promise.all(Array.from({length:8},(_,i)=>new Promise((resolve,reject)=>{
        const w=new Worker(new URL('./worker.mjs',import.meta.url),{workerData:{path:p,options:options(0,`worker-${i}`)}});
        const timer=setTimeout(()=>{w.terminate();reject(new Error('worker timeout'));},8000);
        w.on('error',reject);w.on('message',async message=>{if(message.ready){ready++;if(ready===8)release();await gate;w.postMessage('claim');}else{clearTimeout(timer);if(message.error)reject(new Error(message.error));else resolve(message.value);}});
      })));
      const winners=outcomes.filter(Boolean);assert.equal(winners.length,1);const stored=readJobs(p)[0];assert.equal(stored.worker,winners[0].worker);assert.equal(stored.token,1);console.log(JSON.stringify({run,attempts:8,winner:winners[0],stored}));
    }
  });
  await test('B2-R2: expiry boundary, fresh fencing, wrong owner/token, immutable done',async()=>{
    const p=fixture();add(p,'one');const a=await claim(p,options());
    assert.equal(complete(p,{...a,worker:'forged'},'bad',{now:1}),false);
    assert.equal(complete(p,{...a,token:2},'bad',{now:1}),false);
    assert.equal(complete(p,a,'expired',{now:10}),false);assert.equal(readJobs(p)[0].result,null);
    const b=await claim(p,options(10,'b'));assert.equal(b.token,a.token+1);
    const before=readJobs(p);assert.equal(complete(p,a,'stale',{now:11}),false);assert.deepEqual(readJobs(p),before);
    assert.equal(complete(p,b,'good',{now:19}),true);assert.equal(complete(p,b,'overwrite',{now:19}),false);
    assert.equal(await claim(p,options(1000)),null);assert.equal(readJobs(p)[0].result,'good');
  });
  await test('B2-R3: independent process restarts persist ownership and completion',()=>{
    const p=fixture();add(p,'one');const a=child('claim',p,options(0,'old'));
    assert.equal(child('claim',p,options(9,'new')),null);
    const b=child('claim',p,options(10,'new'));assert.equal(b.token,a.token+1);
    assert.equal(complete(p,a,'stale',{now:11}),false);
    assert.equal(child('complete',p,{claim:b,result:'persisted',options:{now:11}}),true);
    assert.equal(child('read',p)[0].result,'persisted');assert.equal(child('claim',p,options(100)),null);
  });
  await test('B2-R3: invalid leases reject and injected now governs time',async()=>{
    const p=fixture();add(p,'one',100);
    for(const leaseMs of [0,-1,0.1,NaN,Infinity,Number.MAX_SAFE_INTEGER+1]) await assert.rejects(claim(p,options(99,'a',leaseMs)),RangeError);
    assert.equal(await claim(p,options(99)),null);assert.equal((await claim(p,options(100))).leaseUntil,110);
    assert.equal(await claim(p,options(109,'b')),null);assert.equal((await claim(p,options(110,'b'))).token,2);
  });
  await test('B2-R3: busy wait bounded; recovery and error exits close connections',async()=>{
    const p=fixture();add(p,'one');const lock=new DatabaseSync(p);lock.exec('BEGIN IMMEDIATE');const start=performance.now();
    try{await assert.rejects(claim(p,options()),/locked/);}finally{lock.exec('ROLLBACK');lock.close();}
    const elapsedMs=performance.now()-start;assert.ok(elapsedMs<2000,`${elapsedMs}ms`);console.log(JSON.stringify({busyWaitMs:elapsedMs,configuredTimeoutMs:250,retries:0}));
    assert.ok(await claim(p,options()));assert.throws(()=>init(p),/already exists/);
    assert.throws(()=>enqueue(p,{id:'one',payload:'duplicate',dueAt:0}),/UNIQUE/);assert.equal(readJobs(p).length,1);
    const broken=join(directory,'missing-schema.db');await assert.rejects(claim(broken,options()),/no such table/);rmSync(broken);
  });
  console.log(JSON.stringify({status:'PASS',tests:tests.length,passed:tests}));
}finally{rmSync(directory,{recursive:true,force:true});}

import {claim,complete,readJobs} from './service.ts';
import {isMainThread,parentPort,workerData} from 'node:worker_threads';
if(!isMainThread){
  parentPort.once('message',async()=>{try{parentPort.postMessage({value:await claim(workerData.path,workerData.options)});}catch(e){parentPort.postMessage({error:String(e)});}});
  parentPort.postMessage({ready:true});
}else{
  const [action,path,encoded]=process.argv.slice(2); const data=JSON.parse(encoded||'{}');
  const value=action==='claim'?await claim(path,data):action==='complete'?complete(path,data.claim,data.result,data.options):readJobs(path);
  console.log(JSON.stringify(value));
}

export type Person = {id:string; label:string};
export type Search = (query:string, signal?:AbortSignal)=>Promise<Person[]>;
export function mount(root:HTMLElement, search:Search){
 const input=root.querySelector<HTMLInputElement>('#query')!;
 const list=root.querySelector<HTMLElement>('#options')!;
 const status=root.querySelector<HTMLElement>('#status')!;
 const retry=root.querySelector<HTMLButtonElement>('#retry')!;
 const chosen=root.querySelector<HTMLElement>('#chosen')!;
 let items:Person[]=[]; let active=-1; let open=false;
 let generation=0; let controller:AbortController|undefined; let disposed=false;
 let composing=false; let committed='';
 function invalidate(){generation++;controller?.abort();controller=undefined;}
 function render(){
  list.replaceChildren(...(open?items:[]).map((person,i)=>{
   const li=document.createElement('li');li.id='person-'+i;li.role='option';li.textContent=person.label;
   li.setAttribute('aria-selected',String(i===active));return li;
  }));
  const visible=open&&items.length>0;list.hidden=!visible;
  input.setAttribute('aria-expanded',String(visible));
  if(visible&&active>=0&&active<items.length)input.setAttribute('aria-activedescendant','person-'+active);
  else input.removeAttribute('aria-activedescendant');
 }
 async function load(force=false){
  if(disposed||composing)return;
  const query=input.value;
  if(!force&&query===committed)return;
  committed=query;invalidate();const ticket=generation;
  items=[];active=-1;open=false;retry.hidden=true;
  if(!query.trim()){status.textContent='';render();return;}
  controller=new AbortController();const signal=controller.signal;
  status.textContent='Loading';render();
  try{
   const result=await search(query,signal);
   if(disposed||ticket!==generation)return;
   if(!Array.isArray(result)||!result.every(p=>p&&typeof p.id==='string'&&typeof p.label==='string'))throw Error('Invalid search response');
   items=result;active=items.length?0:-1;open=items.length>0;
   status.textContent=items.length+' people';render();
  }catch{
   if(disposed||ticket!==generation)return;
   items=[];active=-1;open=false;status.textContent='Search failed';retry.hidden=false;render();
  }
 }
 function onInput(event:Event){if(!composing&&!(event as InputEvent).isComposing)void load();}
 function onStart(){composing=true;invalidate();items=[];active=-1;open=false;status.textContent='';retry.hidden=true;render();}
 function onEnd(){composing=false;void load(true);}
 function onRetry(){void load(true);input.focus();}
 function onKey(event:KeyboardEvent){
  if(composing||event.isComposing)return;
  if(event.key==='Escape'){event.preventDefault();invalidate();open=false;active=-1;status.textContent='';retry.hidden=true;render();}
  else if((event.key==='ArrowDown'||event.key==='ArrowUp')&&items.length){
   event.preventDefault();if(!open){open=true;active=event.key==='ArrowDown'?0:items.length-1;}
   else active=(active+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;
   render();
  }else if(event.key==='Enter'&&open&&items[active]){
   event.preventDefault();chosen.textContent=items[active].label;open=false;active=-1;render();
  }
 }
 function onPointer(event:MouseEvent){
  const option=(event.target as Element).closest('[role=option]');
  if(!option||!list.contains(option))return;
  event.preventDefault();const index=Array.from(list.children).indexOf(option);
  if(items[index]){chosen.textContent=items[index].label;open=false;active=-1;render();input.focus();}
 }
 input.addEventListener('input',onInput);input.addEventListener('compositionstart',onStart);input.addEventListener('compositionend',onEnd);
 input.addEventListener('keydown',onKey);retry.addEventListener('click',onRetry);list.addEventListener('mousedown',onPointer);render();
 return {dispose(){if(disposed)return;disposed=true;invalidate();input.removeEventListener('input',onInput);input.removeEventListener('compositionstart',onStart);input.removeEventListener('compositionend',onEnd);input.removeEventListener('keydown',onKey);retry.removeEventListener('click',onRetry);list.removeEventListener('mousedown',onPointer);}};
}

